:root {
    --neon-blue: #00f3ff;
    --neon-blue-glow: rgba(0, 243, 255, 0.6);
    --glass-bg: rgba(12, 28, 55, 0.75);
    --glass-border: 2px solid #2a5a9c;
    --text-white: #ffffff;
    --highlight-bg: #dfeeff;
    --highlight-text: #0b1a30
}

.game-container * {
    box-sizing: border-box;
    margin: 0;
    padding: 0
}

.game-container {
    position: relative;
    width: 100%;
    min-height: clamp(500px, 85vh, 900px);
    height: auto;
    background: url(/core/modules/c3251711ea/public/assets/images/background.png) no-repeat center center / cover;
    background-attachment: scroll;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    max-width: 100vw;
    overflow-x: hidden;
    padding: 20px;
    border: 2px solid var(--neon-blue);
    border-radius: 10px;
    box-shadow: 0 0 30px rgb(0 243 255 / .2)
}

.game-container header {
    width: 100%;
    position: relative;
    z-index: 10;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 20px;
    box-sizing: border-box
}

.game-container .header-content {
    text-align: center;
    position: relative
}

.game-container .logout-btn {
    position: absolute;
    top: 0;
    right: 0;
    background: linear-gradient(135deg, rgb(220 50 50 / .8) 0%, rgb(180 30 30 / .9) 100%);
    border: 2px solid rgb(255 100 100 / .6);
    border-radius: 8px;
    padding: 8px 12px;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgb(220 50 50 / .3), inset 0 2px 8px rgb(255 255 255 / .1);
    display: none;
    color: #fff
}

.game-container .logout-btn:hover {
    background: linear-gradient(135deg, rgb(255 70 70 / .9) 0%, rgb(220 50 50) 100%);
    border-color: #ff6b6b;
    box-shadow: 0 0 25px rgb(255 100 100 / .6), inset 0 2px 10px rgb(255 255 255 / .2);
    transform: scale(1.05)
}

.game-container .logout-btn svg {
    display: block
}

.game-container h1 {
    font-family: 'Rajdhani', sans-serif;
    font-size: 3rem;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    text-shadow: 0 0 15px rgb(0 243 255 / .5);
    margin-bottom: 0;
    line-height: 1
}

.game-container h2 {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1.4rem;
    color: var(--neon-blue);
    letter-spacing: 4px;
    text-transform: uppercase;
    position: relative;
    display: inline-block;
    text-shadow: 0 0 10px rgb(0 243 255 / .8)
}

.game-container .timer-display {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: linear-gradient(135deg, rgb(30 60 100 / .9) 0%, rgb(15 35 70 / .95) 100%);
    border: 3px solid rgb(100 180 255 / .6);
    box-shadow: 0 4px 15px rgb(0 100 200 / .3), inset 0 2px 8px rgb(255 255 255 / .1);
    backdrop-filter: blur(10px);
    opacity: 0;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden
}

.game-container .timer-display::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 50%;
    background: linear-gradient(to bottom, rgb(255 255 255 / .15), transparent);
    border-radius: 50%
}

.game-container.game-active .timer-display {
    opacity: 1
}

.game-container .timer-icon {
    font-size: 1.5rem;
    filter: drop-shadow(0 2px 4px rgb(0 0 0 / .5));
    display: none
}

.game-container .timer-value {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1.6rem;
    font-weight: 700;
    color: #b5d0e8;
    text-shadow: 0 0 10px rgb(0 243 255 / .6);
    text-align: center;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center
}

.game-container .timer-display.timer-warning {
    border-color: rgb(243 156 18 / .8);
    background: linear-gradient(135deg, rgb(180 100 20 / .9) 0%, rgb(140 70 15 / .95) 100%);
    box-shadow: 0 0 25px rgb(243 156 18 / .4), inset 0 2px 8px rgb(255 255 255 / .15);
    animation: timer-pulse-warning 1s infinite
}

.timer-display.timer-warning .game-container .timer-value {
    color: #f39c12;
    text-shadow: 0 0 15px rgb(243 156 18 / .8)
}

.timer-display.timer-critical {
    border-color: rgb(231 76 60 / .9);
    background: linear-gradient(135deg, rgb(180 40 40 / .9) 0%, rgb(140 20 20 / .95) 100%);
    box-shadow: 0 0 30px rgb(231 76 60 / .6), inset 0 2px 10px rgb(255 100 100 / .2);
    animation: timer-pulse-critical 0.5s infinite
}

.timer-display.timer-critical .game-container .timer-value {
    color: #e74c3c;
    text-shadow: 0 0 20px rgb(231 76 60)
}

@keyframes timer-pulse-warning {
    0%,
    100% {
        transform: scale(1)
    }
    50% {
        transform: scale(1.08)
    }
}

@keyframes timer-pulse-critical {
    0%,
    100% {
        transform: scale(1)
    }
    50% {
        transform: scale(1.12)
    }
}

#game-ui {
    display: flex;
    flex-direction: row;
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    justify-content: center;
    align-items: center;
    gap: 40px;
    position: relative;
    z-index: 5;
    padding: 20px
}

.game-container main {
    flex: 1;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 0;
    max-width: 1000px
}

.game-container .question-board {
    margin-top: 20px;
    width: 100%;
    max-width: 850px;
    min-height: 180px;
    background: rgb(8 20 40 / .85);
    border: 2px solid #4a9eff;
    border-radius: 15px;
    box-shadow: 0 0 20px rgb(0 150 255 / .4), inset 0 0 40px rgb(0 100 200 / .2);
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 25px clamp(20px, 5vw, 50px);
    position: relative;
    clip-path: polygon(20px 0, calc(100% - 20px) 0, 100% 20px, 100% calc(100% - 20px), calc(100% - 20px) 100%, 20px 100%, 0 calc(100% - 20px), 0 20px);
    backdrop-filter: blur(5px);
    opacity: 0;
    transform: translateY(-20px);
    transition: all 0.8s cubic-bezier(.34, 1.56, .64, 1)
}

.question-board::after {
    content: "";
    position: absolute;
    inset: 5px;
    border: 1px solid rgb(100 200 255 / .3);
    clip-path: inherit;
    pointer-events: none
}

.question-text {
    font-size: 1rem;
    font-weight: 700;
    text-align: center;
    line-height: 1.3;
    color: #fff;
    text-shadow: 0 2px 10px rgb(0 0 0 / .8);
    font-family: 'Roboto', sans-serif;
    overflow-wrap: break-word;
    word-wrap: break-word
}

.game-container .options-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px 60px;
    width: 90%;
    max-width: 1000px;
    opacity: 0;
    transform: translateY(100px);
    transition: all 1.5s cubic-bezier(.34, 1.56, .64, 1) 0.3s
}

.game-container .option-btn {
    background: linear-gradient(180deg, rgb(16 40 70 / .9) 0%, rgb(10 25 50 / .95) 100%);
    border: 2px solid #3a7bc0;
    border-radius: 10px;
    padding: 18px 25px;
    color: #fff;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    position: relative;
    display: flex;
    align-items: flex-start;
    flex-wrap: nowrap;
    gap: 0;
    overflow-wrap: break-word;
    word-wrap: break-word;
    box-shadow: 0 0 10px rgb(0 150 255 / .2), inset 0 0 10px rgb(0 0 0 / .5);
    transition: all 0.2s ease;
    clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px)
}

.option-btn::before {
    content: "";
    position: absolute;
    inset: 2px;
    border: 1px solid rgb(255 255 255 / .1);
    clip-path: inherit
}

.option-btn:hover {
    background: linear-gradient(180deg, rgb(30 70 120 / .9) 0%, rgb(20 50 90 / .95) 100%);
    border-color: #70cfff;
    box-shadow: 0 0 25px rgb(0 200 255 / .5);
    transform: translateY(-2px)
}

.option-btn.correct {
    background: linear-gradient(180deg, rgb(20 100 40 / .9) 0%, rgb(10 60 20 / .95) 100%) !important;
    border-color: #00ff44 !important;
    box-shadow: 0 0 30px rgb(0 255 68 / .6) !important
}

.option-btn.wrong {
    background: linear-gradient(180deg, rgb(120 30 30 / .9) 0%, rgb(80 20 20 / .95) 100%) !important;
    border-color: #ff3333 !important;
    box-shadow: 0 0 30px rgb(255 51 51 / .6) !important
}

.option-btn.selected {
    background: linear-gradient(180deg, rgb(180 130 20 / .9) 0%, rgb(140 70 15 / .95) 100%) !important;
    border-color: #f39c12 !important;
    box-shadow: 0 0 30px rgb(243 156 18 / .6) !important
}

.game-container .label {
    color: gold;
    font-weight: 700;
    margin-right: 15px;
    font-size: 1rem;
    text-shadow: 0 0 10px rgb(255 215 0 / .5);
    flex-shrink: 0;
    align-self: flex-start
}

.game-container .option-text {
    flex: 1;
    min-width: 0;
    word-wrap: break-word;
    overflow-wrap: break-word;
    line-height: 1.4
}

.center-lifelines {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 25px;
    margin: 20px 0 30px 0;
    opacity: 0;
    transform: scale(.8);
    transition: all 1s cubic-bezier(.34, 1.56, .64, 1) 0.2s
}

.game-container.game-active .center-lifelines {
    opacity: 1;
    transform: scale(1)
}

.center-lifeline-btn {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    background: linear-gradient(135deg, rgb(30 60 100 / .9) 0%, rgb(15 35 70 / .95) 100%);
    border: 3px solid rgb(100 180 255 / .6);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgb(0 100 200 / .3), inset 0 2px 8px rgb(255 255 255 / .1);
    position: relative
}

.center-lifeline-btn::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 50%;
    background: linear-gradient(to bottom, rgb(255 255 255 / .15), transparent);
    border-radius: 50%
}

.center-lifeline-btn svg {
    width: 36px;
    height: 36px;
    fill: #b5d0e8;
    filter: drop-shadow(0 2px 4px rgb(0 0 0 / .5));
    z-index: 1
}

.center-lifeline-btn:hover {
    background: linear-gradient(135deg, rgb(50 90 140 / .95) 0%, rgb(30 60 110) 100%);
    border-color: #70cfff;
    box-shadow: 0 0 25px rgb(0 200 255 / .6), inset 0 2px 10px rgb(255 255 255 / .2);
    transform: scale(1.1)
}

.center-lifeline-btn:hover svg {
    fill: #00f3ff
}

.center-lifeline-btn:active,
.center-lifeline-btn.used {
    background: linear-gradient(135deg, rgb(60 60 60 / .7) 0%, rgb(40 40 40 / .8) 100%);
    border-color: #666;
    opacity: .5;
    cursor: not-allowed
}

.center-lifeline-btn.used svg {
    fill: #666
}

.lifeline-counter {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: 'Rajdhani', sans-serif;
    font-size: 1.5rem;
    font-weight: 700;
    color: #fff;
    text-shadow: 0 0 10px var(--neon-blue);
    background: rgb(0 0 0 / .4);
    border-radius: 50%;
    z-index: 5
}

.center-lifeline-btn::after {
    content: attr(data-tooltip);
    position: absolute;
    bottom: 100%;
    left: 50%;
    transform: translateX(-50%) translateY(-10px);
    background: rgb(10 25 50 / .95);
    color: #fff;
    padding: 8px 12px;
    border-radius: 8px;
    font-size: .85rem;
    font-weight: 500;
    white-space: nowrap;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s cubic-bezier(.4, 0, .2, 1);
    border: 1px solid var(--neon-blue);
    box-shadow: 0 0 15px rgb(0 243 255 / .3);
    z-index: 64;
    pointer-events: none
}

.center-lifeline-btn:hover::after {
    opacity: 1;
    visibility: visible;
    transform: translateX(-50%) translateY(-15px)
}

.game-container .money-ladder {
    position: relative;
    width: 280px;
    height: 600px;
    display: flex;
    flex-direction: column;
    opacity: 0;
    transform: translateX(100px);
    transition: all 1.5s cubic-bezier(.34, 1.56, .64, 1) 0.6s
}

.game-container.game-active .question-board {
    opacity: 1;
    transform: translateY(0)
}

.game-container.game-active .options-grid {
    opacity: 1;
    transform: translateY(0)
}

.game-container.game-active .money-ladder {
    opacity: 1;
    transform: translateX(0)
}

.game-container .ladder-panel {
    flex-grow: 1;
    background: linear-gradient(180deg, rgb(10 25 50 / .95) 0%, rgb(5 15 35 / .98) 100%);
    border: 3px solid rgb(58 123 192 / .6);
    border-radius: 25px;
    padding: 15px 10px;
    box-shadow: 0 0 25px rgb(0 100 200 / .3), inset 0 0 40px rgb(0 30 80 / .5);
    backdrop-filter: blur(15px);
    display: flex;
    flex-direction: column;
    gap: 6px;
    position: relative;
    overflow-y: auto;
    overflow-x: hidden
}

.ladder-panel::-webkit-scrollbar {
    width: 6px
}

.ladder-panel::-webkit-scrollbar-track {
    background: rgb(0 0 0 / .3);
    border-radius: 10px
}

.ladder-panel::-webkit-scrollbar-thumb {
    background: rgb(58 123 192 / .6);
    border-radius: 10px
}

.game-container .level-header {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1rem;
    font-weight: 800;
    text-align: center;
    color: #8fa3b8;
    background: rgb(15 35 65 / .4);
    clip-path: polygon(15px 0, calc(100% - 15px) 0, 100% 50%, calc(100% - 15px) 100%, 15px 100%, 0 50%);
    border: none;
    padding: 12px 25px;
    margin: 25px 0 12px 0;
    text-transform: uppercase;
    letter-spacing: 3px;
    position: relative;
    transition: all 0.4s cubic-bezier(.175, .885, .32, 1.275);
    backdrop-filter: blur(10px)
}

.game-container .level-header::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg, transparent 0%, rgb(58 123 192 / .8) 50%, transparent 100%);
    clip-path: polygon(15px 0, calc(100% - 15px) 0, 100% 50%, calc(100% - 15px) 100%, 15px 100%, 0 50%, 16px 2px, 2px 50%, 16px calc(100% - 2px), calc(100% - 16px) calc(100% - 2px), calc(100% - 2px) 50%, calc(100% - 16px) 2px, 16px 2px);
    pointer-events: none
}

.game-container .level-header.active {
    background: linear-gradient(90deg, rgb(0 243 255 / .05) 0%, rgb(0 243 255 / .3) 50%, rgb(0 243 255 / .05) 100%);
    color: #fff;
    text-shadow: 0 0 15px var(--neon-blue);
    transform: scale(1.08) translateY(-2px);
    z-index: 10
}

.game-container .level-header.active::before {
    background: linear-gradient(90deg, transparent 0%, var(--neon-blue) 40%, var(--neon-blue) 60%, transparent 100%);
    box-shadow: 0 0 20px rgb(0 243 255 / .6)
}

.game-container .level-header.completed {
    background: linear-gradient(90deg, rgb(39 174 96 / .05) 0%, rgb(39 174 96 / .2) 50%, rgb(39 174 96 / .05) 100%);
    color: #27ae60;
    text-shadow: 0 0 10px rgb(39 174 96 / .5);
    opacity: .8
}

.game-container .level-header.completed::before {
    background: linear-gradient(90deg, transparent 0%, #27ae60 40%, #27ae60 60%, transparent 100%)
}

.game-container .level-header.active::after {
    content: "";
    position: absolute;
    bottom: -5px;
    left: 50%;
    transform: translateX(-50%);
    width: 40px;
    height: 3px;
    background: var(--neon-blue);
    border-radius: 2px;
    box-shadow: 0 0 10px var(--neon-blue);
    animation: pulse-line 1.5s infinite alternate
}

@keyframes pulse-line {
    from {
        opacity: .4;
        width: 30px
    }
    to {
        opacity: 1;
        width: 50px
    }
}

.question-item {
