    visibility: hidden;
    pointer-events: none
}

.welcome-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 50px;
    z-index: 2;
    padding-bottom: 50px
}

.game-container .welcome-logo {
    width: 450px;
    height: auto;
    max-width: 80%;
    filter: drop-shadow(0 0 20px rgb(0 243 255 / .4));
    animation: pulse-glow 3s infinite alternate
}

@keyframes pulse-glow {
    0% {
        filter: drop-shadow(0 0 20px rgb(0 243 255 / .4));
        transform: scale(1)
    }
    100% {
        filter: drop-shadow(0 0 40px rgb(0 243 255 / .7));
        transform: scale(1.02)
    }
}

.start-btn {
    padding: 10px 50px
}

.game-container .start-btn {
    background: linear-gradient(180deg, #0a2e52 0%, #05182d 100%);
    color: #fff;
    font-family: 'Rajdhani', sans-serif;
    font-size: 1rem;
    font-weight: 700;
    border: 2px solid #3a7bc0;
    border-radius: 50px;
    cursor: pointer;
    text-transform: uppercase;
    letter-spacing: 2px;
    box-shadow: 0 0 20px rgb(0 150 255 / .3), inset 0 0 20px rgb(0 150 255 / .1);
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden
}

.start-btn::before {
    content: "";
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgb(255 255 255 / .2), transparent);
    transition: 0.5s
}

.start-btn:hover {
    background: linear-gradient(180deg, #104070 0%, #0a2540 100%);
    border-color: #00f3ff;
    box-shadow: 0 0 30px rgb(0 243 255 / .6), inset 0 0 30px rgb(0 243 255 / .2);
    transform: scale(1.05)
}

.start-btn:hover::before {
    left: 100%
}

.game-container .version {
    position: absolute;
    bottom: 20px;
    right: 20px;
    color: rgb(255 255 255 / .5);
    font-size: .8rem;
    font-family: 'Roboto', sans-serif;
    letter-spacing: 1px
}

.welcome-screen::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at center, rgb(5 11 20 / .4) 0%, rgb(5 11 20 / .9) 100%);
    z-index: 1
}

.signup-panel {
    background: rgb(10 25 50 / .95);
    border: 2px solid #3a7bc0;
    border-radius: 20px;
    padding: 40px 60px;
    z-index: 66;
    display: flex;
    flex-direction: column;
    align-items: center;
    box-shadow: 0 0 30px rgb(0 150 255 / .4), inset 0 0 50px rgb(0 20 40 / .8);
    backdrop-filter: blur(15px);
    width: 600px;
    max-width: 90%;
    position: relative;
    animation: fadeInScale 0.5s ease-out
}

@keyframes fadeInScale {
    from {
        opacity: 0;
        transform: scale(.9)
    }
    to {
        opacity: 1;
        transform: scale(1)
    }
}

.signup-panel .game-container h2 {
    font-family: 'Rajdhani', sans-serif;
    color: #fff;
    font-size: 2.2rem;
    margin-bottom: 30px;
    text-shadow: 0 0 10px rgb(0 243 255 / .8);
    text-align: center;
    border-bottom: 2px solid var(--neon-blue);
    padding-bottom: 15px;
    width: 100%;
    letter-spacing: 2px
}

.signup-panel form {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 25px
}

.input-group {
    display: flex;
    flex-direction: column;
    gap: 10px
}

.input-group label {
    color: var(--neon-blue);
    font-family: 'Rajdhani', sans-serif;
    font-weight: 700;
    letter-spacing: 1.5px;
    font-size: 1.2rem;
    text-shadow: 0 0 5px rgb(0 243 255 / .3)
}

.input-group input,
.input-group select {
    background: rgb(5 15 30 / .7);
    border: 1px solid #3a7bc0;
    border-radius: 8px;
    padding: 15px 20px;
    color: #fff;
    font-family: 'Roboto', sans-serif;
    font-size: 1.1rem;
    outline: none;
    transition: all 0.3s ease;
    width: 100%
}

.input-group input::placeholder {
    color: rgb(255 255 255 / .3);
    font-size: .9rem
}

.input-group input:focus,
.input-group select:focus {
    border-color: var(--neon-blue);
    box-shadow: 0 0 20px rgb(0 243 255 / .2);
    background: rgb(10 30 60 / .9)
}

.input-group select option {
    background: #05182d;
    color: #fff;
    padding: 10px
}

.start-btn::before {
    pointer-events: none
}

.small-btn {
    margin-top: 10px;
    padding: 15px 40px;
    font-size: 1.6rem;
    width: 100%;
    background: linear-gradient(180deg, #3a7bc0 0%, #0a2e52 100%);
    border-color: #00f3ff
}

.small-btn:hover {
    background: linear-gradient(180deg, #4da3ff 0%, #104070 100%);
    box-shadow: 0 0 40px rgb(0 243 255 / .5)
}

.cyber-rules-wrapper {
    background: rgb(10 25 45 / .95);
    border: 3px solid var(--neon-blue);
    border-radius: 30px;
    padding: 40px;
    width: 850px;
    max-width: 95%;
    box-shadow: 0 0 50px rgb(0 243 255 / .3), inset 0 0 30px rgb(0 243 255 / .1);
    backdrop-filter: blur(15px);
    text-align: center;
    z-index: 10
}

.rules-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 25px;
    margin: 30px 0;
    text-align: left
}

.rule-card {
    background: rgb(255 255 255 / .05);
    border: 1px solid rgb(0 243 255 / .3);
    border-radius: 20px;
    padding: 20px;
    transition: all 0.3s ease
}

.rule-card:hover {
    background: rgb(0 243 255 / .1);
    border-color: var(--neon-blue);
    transform: translateY(-5px)
}

.rule-header {
    font-family: 'Rajdhani', sans-serif;
    color: var(--neon-blue);
    font-weight: 700;
    font-size: 1.2rem;
    margin-bottom: 12px;
    letter-spacing: 2px;
    text-transform: uppercase;
    border-bottom: 1px solid rgb(0 243 255 / .2);
    padding-bottom: 8px
}

.rule-list {
    list-style: none;
    padding: 0;
    margin: 0
}

.rule-list li {
    font-size: .95rem;
    margin-bottom: 6px;
    padding-left: 15px;
    position: relative;
    color: #b5d0e8
}

.rule-list li::before {
    content: "▹";
    position: absolute;
    left: 0;
    color: var(--neon-blue)
}

.rule-card p {
    font-size: .95rem;
    line-height: 1.5;
    color: #b5d0e8;
    margin: 0
}

@media (max-width:900px) {
    .cyber-rules-wrapper {
        padding: 30px
    }
    .rules-grid {
        gap: 20px
    }
}

@media (max-width:768px) {
    .game-container .welcome-screen {
        justify-content: flex-start;
        padding-top: 40px
    }
    .cyber-rules-wrapper {
        padding: 25px 20px;
