.game-container .game-over-screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url(/core/modules/c3251711ea/public/assets/images/background.png) no-repeat center center / cover;
    z-index: 67;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    transition: opacity 0.5s ease-in-out, visibility 0.5s;
    backdrop-filter: blur(8px)
}

.game-over-screen::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at center, rgb(30 10 10 / .6) 0%, rgb(5 0 0 / .95) 100%);
    z-index: 1
}

.game-over-content {
    background: rgb(15 5 5 / .9);
    border: 3px solid #f33;
    border-radius: 25px;
    padding: 50px;
    z-index: 10;
    text-align: center;
    box-shadow: 0 0 50px rgb(255 0 0 / .3), inset 0 0 30px rgb(255 0 0 / .1);
    width: 650px;
    max-width: 90%;
    animation: fadeInScale 0.5s ease-out
}

.game-over-content .game-container h2 {
    color: #f33;
    font-size: 3.5rem;
    margin-bottom: 30px;
    text-shadow: 0 0 20px rgb(255 51 51 / .8);
