    border: 1px solid rgb(255 51 51 / .3);
    border-radius: 15px;
    padding: 20px;
    transition: transform 0.3s ease
}

.stat-item:hover {
    transform: translateY(-5px);
    background: rgb(255 51 51 / .1);
    border-color: #f33
}

.stat-label {
    font-family: 'Rajdhani', sans-serif;
    font-size: 1rem;
    color: #888;
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 10px
}

.stat-value {
    font-size: 2.2rem;
    font-weight: 700;
    color: #fff;
    text-shadow: 0 0 10px rgb(255 255 255 / .5)
}

.restart-btn {
    background: linear-gradient(180deg, #ff3333 0%, #a01010 100%);
    border-color: #f66;
    box-shadow: 0 0 30px rgb(255 51 51 / .4)
}

.restart-btn:hover {
    background: linear-gradient(180deg, #ff4d4d 0%, #cc0000 100%);
    box-shadow: 0 0 40px rgb(255 51 51 / .7)
}

.revival-btn {
    background: linear-gradient(180deg, #00c853 0%, #007e33 100%) !important;
    border: 2px solid #b2ff59 !important;
    color: #000 !important;
    font-weight: 800 !important;
    margin-top: 20px !important;
    width: 100% !important;
    box-shadow: 0 0 25px rgb(0 200 83 / .4) !important;
    clip-path: polygon(15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%, 0 15px);
    transition: all 0.3s ease
}

.revival-btn:hover {
    background: linear-gradient(180deg, #00e676 0%, #00c853 100%) !important;
    box-shadow: 0 0 40px rgb(0 200 83 / .7) !important;
    transform: translateY(-3px)
}

.game-container .hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none
}

@media (max-width:768px) {
    .game-over-content {
        padding: 40px 30px;
        width: 85%;
        max-width: 500px
    }
    .game-over-content h2 {
        font-size: 2.5rem !important;
        margin-bottom: 25px
    }
    .stats-container {
        grid-template-columns: repeat(2, 1fr);
