.game-container .victory-screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgb(5 10 20 / .95);
    backdrop-filter: blur(15px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 68;
    transition: all 0.5s ease
}

.victory-content {
    position: relative;
    width: 85%;
    max-width: 600px;
    background: linear-gradient(135deg, rgb(15 40 75 / .95) 0%, rgb(10 30 60 / .98) 100%);
    border: 3px solid rgb(0 243 255 / .5);
    border-radius: 25px;
    padding: 40px 35px;
    box-shadow: 0 0 50px rgb(0 243 255 / .4), inset 0 0 60px rgb(0 100 150 / .2);
    backdrop-filter: blur(20px);
    text-align: center;
    animation: victoryEntrance 0.8s cubic-bezier(.34, 1.56, .64, 1);
    clip-path: polygon(25px 0, calc(100% - 25px) 0, 100% 25px, 100% calc(100% - 25px), calc(100% - 25px) 100%, 25px 100%, 0 calc(100% - 25px), 0 25px)
}

.victory-content::after {
    content: "";
    position: absolute;
    inset: 5px;
    border: 1px solid rgb(100 200 255 / .3);
    clip-path: inherit;
    pointer-events: none
}

@keyframes victoryEntrance {
    0% {
        opacity: 0;
        transform: scale(.85) translateY(40px)
    }
    100% {
        opacity: 1;
        transform: scale(1) translateY(0)
    }
}

.trophy-container {
    position: relative;
    width: 100px;
    height: 100px;
    margin: 0 auto 25px
}

.trophy-icon {
    font-size: 5rem;
    animation: trophyBounce 2s infinite ease-in-out;
    position: relative;
    z-index: 2;
    filter: drop-shadow(0 8px 25px rgb(255 215 0 / .6))
}

@keyframes trophyBounce {
    0%,
    100% {
        transform: translateY(0) rotate(-5deg)
    }
    50% {
        transform: translateY(-15px) rotate(5deg)
    }
}

.trophy-glow {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 150px;
    height: 150px;
    background: radial-gradient(circle, rgb(255 215 0 / .3) 0%, rgb(255 215 0 / .1) 50%, transparent 70%);
    border-radius: 50%;
    animation: glowPulse 2s infinite ease-in-out;
    z-index: 1
}

@keyframes glowPulse {
    0%,
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: .5
    }
    50% {
        transform: translate(-50%, -50%) scale(1.15);
        opacity: 1
    }
}

.victory-title {
    font-family: 'Rajdhani', sans-serif;
    font-size: 2.5rem;
    font-weight: 700;
    background: linear-gradient(90deg, #00f3ff 0%, #00ff88 50%, #00f3ff 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: #fff0;
    background-clip: text;
    margin-bottom: 12px;
    letter-spacing: 3px;
    text-transform: uppercase;
    animation: titleGlow 3s infinite alternate;
    filter: drop-shadow(0 0 20px rgb(0 243 255 / .5))
}

@keyframes titleGlow {
    0% {
        filter: drop-shadow(0 0 15px rgb(0 243 255 / .4))
    }
    100% {
        filter: drop-shadow(0 0 30px rgb(0 243 255 / .8))
    }
}

.victory-subtitle {
    font-family: 'Roboto', sans-serif;
    font-size: 1.1rem;
    color: #b5d0e8;
    margin-bottom: 30px;
    letter-spacing: 1px
}

.victory-stats-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin: 30px 0
}

.victory-stat-card {
    background: linear-gradient(135deg, rgb(30 60 100 / .6) 0%, rgb(15 35 70 / .8) 100%);
    border: 2px solid rgb(0 243 255 / .3);
    border-radius: 15px;
    padding: 20px 15px;
    transition: all 0.3s ease;
    position: relative;
    overflow: hidden;
    clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px)
}

.victory-stat-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgb(255 255 255 / .1), transparent);
    transition: left 0.5s ease
}

.victory-stat-card:hover::before {
    left: 100%
}

.victory-stat-card:hover {
    transform: translateY(-5px) scale(1.03);
    border-color: #00f3ff;
    box-shadow: 0 8px 30px rgb(0 243 255 / .4)
}

.victory-stat-label {
    font-family: 'Rajdhani', sans-serif;
    font-size: .9rem;
    color: #8fa3b8;
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-bottom: 6px
}

.victory-stat-value {
    font-family: 'Rajdhani', sans-serif;
    font-size: 2.2rem;
    font-weight: 700;
    color: #00f3ff;
    text-shadow: 0 0 18px rgb(0 243 255 / .6)
