.cyber-signup-wrapper,
.cyber-country-wrapper {
    background: rgb(8 20 40 / .95);
    border: 3px solid #00f3ff;
    border-radius: 20px;
    padding: 50px 40px;
    position: relative;
    box-shadow: 0 0 60px rgb(0 243 255 / .4), inset 0 0 40px rgb(0 100 150 / .1);
    backdrop-filter: blur(25px);
    overflow: hidden;
    max-width: 650px;
    width: 90%;
    z-index: 69;
    margin: auto
}

.cyber-tabs {
    display: flex;
    gap: 10px;
    margin-bottom: 30px;
    border-bottom: 1px solid rgb(0 243 255 / .2);
    padding-bottom: 15px
}

.cyber-tab {
    background: #fff0;
    border: 1px solid rgb(0 243 255 / .3);
    color: rgb(0 243 255 / .6);
    padding: 10px 25px;
    cursor: pointer;
    font-family: 'Rajdhani', sans-serif;
    font-weight: 700;
    letter-spacing: 1.5px;
    border-radius: 5px;
    transition: all 0.3s ease
