.tutor-container,
.tutor-container-fluid,
.tutor-container-xxl,
.tutor-container-xl,
.tutor-container-lg,
.tutor-container-md,
.tutor-container-sm {
    width: 100%;
    padding-right: var(--tutor-gutter-x, .75rem);
    padding-left: var(--tutor-gutter-x, .75rem);
    margin-left: auto;
    margin-right: auto
}

@media (min-width:576px) {
    .tutor-container-sm,
    .tutor-container {
        max-width: 540px
    }
}

@media (min-width:768px) {
    .tutor-container-md,
    .tutor-container-sm,
    .tutor-container {
        max-width: 720px
    }
}

@media (min-width:992px) {
    .tutor-container-lg,
    .tutor-container-md,
    .tutor-container-sm,
    .tutor-container {
        max-width: 960px
    }
}

@media (min-width:1200px) {
    .tutor-container-xl,
    .tutor-container-lg,
    .tutor-container-md,
    .tutor-container-sm,
    .tutor-container {
        max-width: 1140px
    }
}

@media (min-width:1400px) {
    .tutor-container-xxl,
    .tutor-container-xl,
    .tutor-container-lg,
    .tutor-container-md,
    .tutor-container-sm,
    .tutor-container {
        max-width: 1320px
    }
}

.tutor-row {
    --tutor-gutter-x: 1.5rem;
    --tutor-gutter-y: 0;
    margin-top: calc(-1*var(--tutor-gutter-y));
    margin-right: calc(-.5*var(--tutor-gutter-x));
    margin-left: calc(-.5*var(--tutor-gutter-x));
    flex-wrap: wrap;
    display: flex
}

.tutor-row>* {
    box-sizing: border-box;
    width: 100%;
    max-width: 100%;
    padding-right: calc(var(--tutor-gutter-x)*.5);
    padding-left: calc(var(--tutor-gutter-x)*.5);
    margin-top: var(--tutor-gutter-y);
    flex-shrink: 0
}

.tutor-col {
    flex: 1 0
}

.tutor-row-cols-auto>* {
    flex: none;
    width: auto
