    padding: 16px;
    font-size: 16px;
    font-weight: 500;
    line-height: 1.6
}

.tutor-table tr td>a:not(.tutor-btn):not(.tutor-iconic-btn):not(.quiz-manual-review-action),
.tutor-table tr td .tutor-table-link {
    color: var(--tutor-body-color);
