.tutor-password-strength-hint {
    justify-content: space-between;
    align-items: center;
    margin-top: 7px;
    display: flex
}

.tutor-password-strength-hint .indicator {
    justify-content: space-between;
    align-items: center;
    gap: 25px;
    height: 10px;
    margin: 10px 0;
    display: none
}

.tutor-password-strength-hint .indicator span {
    background: #d3d3d3;
    border-radius: 5px;
    width: 72px;
    height: 2px;
    position: relative
}

.tutor-password-strength-hint .indicator span.active:before {
    content: "";
    border-radius: 5px;
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0
}

.tutor-password-strength-hint .indicator span.weak:before {
    background-color: #f44337
}

.tutor-password-strength-hint .indicator span.medium:before {
    background-color: #ed9700
}

.tutor-password-strength-hint .indicator span.strong:before {
    background-color: var(--tutor-color-success)
}

.tutor-password-strength-hint .indicator span:nth-child(2) {
    margin: 0 3px
}

.tutor-password-strength-hint .text {
    text-align: right;
    text-transform: capitalize;
    display: none
}

.tutor-password-strength-hint .text.weak {
    color: #f44337
}

.tutor-password-strength-hint .text.medium {
    color: #ed9700
}

.tutor-password-strength-hint .text.strong {
    color: var(--tutor-color-success)
}

.tutor-card {
    word-wrap: break-word;
    background-color: #fff;
    border-radius: 6px;
    flex-direction: column;
    min-width: 0;
    display: flex;
    position: relative
}

.tutor-card:not(.tutor-no-border) {
    border: 1px solid var(--tutor-border-color)
}

.tutor-card-header {
    border-radius: 5px 5px 0 0;
    justify-content: space-between;
    align-items: center;
    padding: 16px 20px;
    display: flex
}

.tutor-card-header:not(.tutor-no-border) {
    border-bottom: 1px solid var(--tutor-border-color)
}

.tutor-card-title {
    margin: 0;
    font-size: 16px;
    font-weight: 500
}

.tutor-card-body {
    flex: auto;
    padding: 20px
}

.tutor-card-footer {
    border-radius: 0 0 5px 5px;
    padding: 16px 20px
}

.tutor-card-footer:not(.tutor-no-border) {
    border-top: 1px solid var(--tutor-border-color)
}

.tutor-card-image {
    border-radius: 5px
}

.tutor-card-image-top {
    border-radius: 5px 5px 0 0
}

.tutor-card-image-right {
    border-radius: 0 5px 5px 0
}

.tutor-card-image-bottom {
    border-radius: 0 0 5px 5px
}

.tutor-card-image-left {
    border-radius: 5px 0 0 5px
}

.tutor-card-secondary {
    border: 2px solid #e0e2ea
}

.tutor-card.is-selected {
    background-color: rgba(var(--tutor-color-primary-rgb), .05);
    border-color: rgba(var(--tutor-color-primary-rgb), .4)
}

.tutor-card.is-active {
    background-color: rgba(var(--tutor-color-primary-rgb), .05);
    border-color: var(--tutor-color-primary)
}

.tutor-card-sm .tutor-card-header {
    padding: 10px 16px
}

.tutor-card-sm .tutor-card-body,
.tutor-card-sm .tutor-card-footer {
    padding: 16px
}

.tutor-card-md .tutor-card-header {
    padding: 24px 32px
}

.tutor-card-md .tutor-card-body {
    padding: 32px
}

.tutor-card-md .tutor-card-footer {
    padding: 24px 32px
}

.tutor-card-list {
    border-radius: 6px;
    flex-direction: column;
    margin-bottom: 0;
    padding-left: 0;
    display: flex
}

.tutor-card-list:first-child {
    border-top-width: 0;
    border-top-left-radius: 5px;
    border-top-right-radius: 5px
}

.tutor-card-list-item {
    color: var(--tutor-body-color);
    background-color: #fff;
    text-decoration: none;
    display: block;
    position: relative
}

.tutor-card-list-item:nth-child(2n) {
    background-color: #fcfcfd
}

.tutor-card-list-item:not(:last-child) {
    border-bottom: 1px solid #cdcfd5
}

.tutor-card-list-item:first-child {
    border-top-left-radius: 6px;
    border-top-right-radius: 6px
}

.tutor-card-list-item:last-child {
    border-bottom-right-radius: 6px;
    border-bottom-left-radius: 6px
}

@media (min-width:1200px) {
    .tutor-card-list-horizontal {
        flex-direction: row
    }
    .tutor-card-list-horizontal .tutor-card-list-item {
        border-bottom: 0;
        border-radius: 6px;
        flex-grow: 1;
        flex-shrink: 0
    }
    .tutor-card-list-horizontal .tutor-card-list-item:not(:last-child) {
        border-right: 1px solid #cdcfd5;
        border-top-right-radius: 0;
        border-bottom-right-radius: 0
    }
}

.tutor-accordion-item {
    background-color: #fff;
    border: 1px solid #e0e2ea;
    border-radius: 6px
}

.tutor-accordion-item:not(:last-child) {
    margin-bottom: 10px
}

@media (min-width:992px) {
    .tutor-accordion-item:not(:last-child) {
        margin-bottom: 20px
    }
}

.tutor-accordion-item-header {
    color: var(--tutor-color-secondary);
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    cursor: pointer;
    background-color: #fcfcfd;
    border-radius: 6px;
    padding: 16px 40px 16px 20px;
    font-size: 20px;
    font-weight: 500;
    line-height: 1.4;
    transition: all .3s ease-in;
    position: relative;
    margin: 0 !important
}

.tutor-accordion-item-header:after {
    content: "";
    color: var(--tutor-color-primary);
    font-size: 16px;
    font-weight: 400;
    transition: all .15s;
    position: absolute;
    top: 50%;
    right: 16px;
    transform: translateY(-50%)rotate(0);
    font-family: tutor !important
}

.tutor-accordion-item-header:hover {
    color: var(--tutor-color-primary)
}

.tutor-accordion-item-header.is-active {
    color: var(--tutor-color-primary);
    background-color: #eff1f6;
    border-radius: 6px 6px 0 0
}

.tutor-accordion-item-header.is-active:after {
    transform: translateY(-50%)rotate(-90deg)
}

.tutor-accordion-item-header .tooltip-wrap.tooltip-icon {
    margin-left: 8px;
    font-size: 16px;
    position: relative;
    top: 1px
}

.tutor-accordion-item-body {
    overflow: hidden
}

.tutor-accordion-item-body-content {
    border-top: 1px solid #e0e2ea;
    padding: 0 16px
}

.tutor-modal {
    z-index: 99999;
    outline: 0;
    width: 100%;
    height: 100%;
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    overflow-x: hidden;
    overflow-y: auto
}

.tutor-modal-open {
    overflow: hidden
}

.tutor-modal.tutor-is-active,
.tutor-modal-active {
    display: block
}

.tutor-modal-overlay {
    z-index: -1;
    background-color: rgb(0 0 0 / .75);
    width: 100%;
    height: 100%;
    position: fixed;
    top: 0;
    left: 0
}

.tutor-modal-window {
    pointer-events: none;
    align-items: center;
    width: auto;
    max-width: 640px;
    min-height: calc(100% - 96px);
    margin: 48px auto;
    display: flex;
    position: relative
}

.tutor-modal-window-lg {
    max-width: 880px
}

.tutor-modal-window-md {
    max-width: 520px
}

.tutor-modal-window-sm {
    max-width: 430px
}

.tutor-modal-content {
    pointer-events: auto;
    border: 1px solid var(--tutor-border-color);
    background-color: #eff1f7;
    background-clip: padding-box;
    border-radius: 16px;
    outline: 0;
    flex-direction: column;
    width: 100%;
    display: flex;
    position: relative
}

.tutor-modal-content-white {
    background-color: #fff
}

.tutor-modal-header,
.tutor-modal-footer {
    background-color: #fff;
    flex-shrink: 0;
    justify-content: space-between;
    align-items: center;
    padding: 16px 32px;
    display: flex
}

.tutor-modal-header {
    border-bottom: 1px solid var(--tutor-border-color);
    border-top-left-radius: 16px;
    border-top-right-radius: 16px
}

.tutor-modal-header .tutor-modal-close {
    margin-right: -16px
}

.tutor-modal .tutor-modal-close-o {
    z-index: 1;
    font-size: 20px;
    position: absolute;
    top: 16px;
    right: 16px
