    --camsprep-bg: #FFFFFF;
    --camsprep-bg-soft: #F6F7FB;
    --camsprep-text: #1F2937;
    --camsprep-text-muted: #6B7280;
    --camsprep-border: #E5E7EB;
    --camsprep-success: #25D366;
    --camsprep-offset-x: 24px;
    --camsprep-offset-y: 24px;
    --camsprep-z: 999999;
    position: fixed;
    bottom: 0;
    right: 0;
    width: 0;
    height: 0;
    z-index: var(--camsprep-z);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
    color: var(--camsprep-text);
    font-size: 14px;
    line-height: 1.5
}

#camsprep-chat-root *,
#camsprep-chat-root *::before,
#camsprep-chat-root *::after {
    box-sizing: border-box
}

#camsprep-chat-root[data-camsprep-position="bottom-left"] .camsprep-bubble,
#camsprep-chat-root[data-camsprep-position="bottom-left"] .camsprep-greeting,
#camsprep-chat-root[data-camsprep-position="bottom-left"] .camsprep-panel {
    left: var(--camsprep-offset-x);
    right: auto
}

.camsprep-bubble {
    position: fixed;
    bottom: var(--camsprep-offset-y);
    right: var(--camsprep-offset-x);
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--camsprep-primary);
    border: none;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 16px rgb(0 0 0 / .15);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    z-index: var(--camsprep-z);
    padding: 0
}

.camsprep-bubble:hover {
    transform: scale(1.06);
    box-shadow: 0 6px 20px rgb(0 0 0 / .18)
}

.camsprep-bubble:focus-visible {
    outline: 3px solid var(--camsprep-primary-light);
    outline-offset: 2px
}

.camsprep-bubble svg {
    width: 28px;
    height: 28px;
    fill: #fff
}

.camsprep-bubble[hidden] {
    display: none
}

.camsprep-greeting {
    position: fixed;
    bottom: calc(var(--camsprep-offset-y) + 68px);
    right: var(--camsprep-offset-x);
    background: var(--camsprep-primary);
    color: #fff;
    padding: 8px 14px;
    border-radius: 8px;
    font-size: 13px;
    box-shadow: 0 4px 12px rgb(0 0 0 / .15);
    cursor: pointer;
    z-index: var(--camsprep-z);
    animation: camsprep-fade-in-up 0.4s 0.8s both
}

.camsprep-greeting::after {
    content: '';
    position: absolute;
    bottom: -6px;
    right: 20px;
    width: 12px;
    height: 12px;
    background: var(--camsprep-primary);
    transform: rotate(45deg)
}

.camsprep-greeting.camsprep-fade-out {
    animation: camsprep-fade-out 0.4s forwards
}

.camsprep-greeting[hidden] {
    display: none
}

@keyframes camsprep-fade-in-up {
    from {
        opacity: 0;
        transform: translateY(8px)
    }
    to {
        opacity: 1;
        transform: translateY(0)
    }
}

@keyframes camsprep-fade-out {
    to {
        opacity: 0;
        transform: translateY(8px)
    }
}

.camsprep-panel {
    position: fixed;
    bottom: var(--camsprep-offset-y);
    right: var(--camsprep-offset-x);
    width: 380px;
    height: 640px;
    max-height: calc(100vh - 48px);
    background: var(--camsprep-bg);
    border-radius: 16px;
    box-shadow: 0 12px 40px rgb(0 0 0 / .2);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    z-index: var(--camsprep-z);
    animation: camsprep-panel-in 0.25s ease-out
}

.camsprep-panel[hidden] {
    display: none
}

@keyframes camsprep-panel-in {
    from {
        opacity: 0;
        transform: translateY(12px) scale(.98)
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1)
    }
}

.camsprep-header {
    background: var(--camsprep-primary);
    color: var(--camsprep-header-text);
    flex-shrink: 0;
    position: relative;
    background-image: radial-gradient(circle at 20% 30%, rgb(255 255 255 / .08) 0, transparent 40%), radial-gradient(circle at 80% 70%, rgb(255 255 255 / .06) 0, transparent 40%)
}

.camsprep-header-card {
    padding: 16px;
    display: flex;
    align-items: center;
    gap: 12px
}

.camsprep-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: #fff;
    color: var(--camsprep-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 15px;
    overflow: hidden;
    flex-shrink: 0;
    border: 2px solid rgb(255 255 255 / .4)
}

.camsprep-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover
}

.camsprep-title {
    flex: 1;
    min-width: 0
}

.camsprep-name {
    font-size: 14px;
    font-weight: 600;
    line-height: 1.3
}

.camsprep-sub {
    font-size: 12px;
    opacity: .85;
    margin-top: 2px
}

.camsprep-close {
    background: #fff0;
    border: none;
    color: var(--camsprep-header-text);
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center
}

.camsprep-close:hover {
    background: rgb(255 255 255 / .15)
}

.camsprep-close svg {
    width: 18px;
    height: 18px;
    fill: currentColor
}

.camsprep-tab-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: var(--camsprep-bg)
}

.camsprep-tab-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden
}

.camsprep-tab-content[hidden] {
    display: none
}

.camsprep-tab-scroll {
    flex: 1;
    overflow-y: auto;
    padding: 16px
}

.camsprep-tab-title {
    font-size: 15px;
    font-weight: 500;
    color: var(--camsprep-primary);
    margin: 0 0 14px;
    line-height: 1.4
}

.camsprep-tab-title-inline {
    padding: 12px 16px 0;
    margin: 0
}

.camsprep-tab-empty {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    text-align: center;
    color: var(--camsprep-text-muted)
}

.camsprep-status-row {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    font-size: 11px;
    color: var(--camsprep-text-muted);
    border-bottom: 1px solid var(--camsprep-border);
    background: var(--camsprep-bg-soft);
    flex-shrink: 0
}

.camsprep-status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--camsprep-success);
    flex-shrink: 0
}

.camsprep-messages {
    flex: 1;
    overflow-y: auto;
    padding: 14px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    background: var(--camsprep-bg-soft);
    scrollbar-width: thin
}

.camsprep-messages::-webkit-scrollbar {
    width: 6px
}

.camsprep-messages::-webkit-scrollbar-thumb {
    background: #c5c4be;
    border-radius: 3px
}

.camsprep-msg {
    padding: 10px 12px;
    border-radius: 14px;
    font-size: 13.5px;
    max-width: 85%;
    line-height: 1.5;
    word-wrap: break-word;
    animation: camsprep-msg-in 0.2s ease-out
}

@keyframes camsprep-msg-in {
    from {
        opacity: 0;
        transform: translateY(4px)
    }
    to {
        opacity: 1;
        transform: translateY(0)
    }
}

.camsprep-msg-bot {
    background: #fff;
    border: 1px solid var(--camsprep-border);
    align-self: flex-start
}

.camsprep-msg-user {
    background: var(--camsprep-primary);
    color: #fff;
    align-self: flex-end;
    border-bottom-right-radius: 4px
}

.camsprep-msg strong {
    font-weight: 600
}

.camsprep-msg-bot strong {
    color: var(--camsprep-primary)
}

.camsprep-msg a {
    color: var(--camsprep-primary);
    text-decoration: underline
}

.camsprep-msg-user a {
    color: #fff
}

.camsprep-system-note {
    font-size: 11px;
    color: var(--camsprep-text-muted);
    text-align: center;
    padding: 6px 12px;
    background: rgb(255 255 255 / .7);
    border-radius: 12px;
    align-self: center;
    max-width: 95%
}

.camsprep-typing {
    display: inline-flex;
    gap: 3px;
    align-items: center
}

.camsprep-typing span {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #888780;
    animation: camsprep-bounce 1.2s infinite
}

.camsprep-typing span:nth-child(2) {
    animation-delay: 0.15s
}

.camsprep-typing span:nth-child(3) {
    animation-delay: 0.3s
}

@keyframes camsprep-bounce {
    0%,
    60%,
    100% {
        transform: translateY(0);
        opacity: .5
    }
    30% {
        transform: translateY(-4px);
        opacity: 1
    }
}

.camsprep-quick-actions {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 6px 0 4px;
    align-self: stretch;
    width: 100%
}

.camsprep-quick-action {
    background: #fff;
    border: 1px solid var(--camsprep-primary-light);
    border-radius: 12px;
    padding: 12px 14px;
    cursor: pointer;
    font-family: inherit;
    display: flex;
    align-items: center;
    gap: 12px;
    text-align: left;
    transition: background 0.15s, border-color 0.15s, transform 0.1s;
    color: var(--camsprep-text)
}

.camsprep-quick-action:hover {
    background: var(--camsprep-bg-soft);
    border-color: var(--camsprep-primary);
    transform: translateX(2px)
}

.camsprep-quick-action-icon {
    font-size: 22px;
    flex-shrink: 0;
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--camsprep-bg-soft);
    border-radius: 50%
}

.camsprep-quick-action-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0
}

.camsprep-quick-action-label {
    font-size: 13px;
    font-weight: 500;
    color: var(--camsprep-primary-dark)
}

.camsprep-quick-action-sub {
    font-size: 11.5px;
    color: var(--camsprep-text-muted)
}

.camsprep-quick-action-arrow {
    color: var(--camsprep-primary);
    font-size: 16px;
    flex-shrink: 0
}

.camsprep-suggestions {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
    margin: 4px 0
}

.camsprep-suggestion {
    background: #fff;
    border: 1px solid var(--camsprep-primary-light);
    color: var(--camsprep-primary-dark);
    font-size: 11.5px;
    padding: 6px 10px;
    border-radius: 14px;
    cursor: pointer;
    font-family: inherit
}

.camsprep-suggestion:hover {
    background: #E6F1FB
}

.camsprep-feedback {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    opacity: .6;
    transition: opacity 0.2s
}

.camsprep-msg-bot:hover .camsprep-feedback {
    opacity: 1
}

.camsprep-feedback-btn {
    background: none;
    border: 1px solid var(--camsprep-border);
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 12px;
    cursor: pointer;
    line-height: 1.2
}

.camsprep-feedback-btn:hover {
    background: var(--camsprep-bg-soft)
}

.camsprep-feedback-btn.camsprep-active {
    background: var(--camsprep-bg-soft);
    border-color: var(--camsprep-primary)
}

.camsprep-composer {
    padding: 10px 12px;
    background: #fff;
    border-top: 1px solid var(--camsprep-border);
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0
}

.camsprep-composer input[type="text"] {
    flex: 1;
    background: var(--camsprep-bg-soft);
    border: none;
    padding: 10px 14px;
    border-radius: 20px;
    font-size: 13.5px;
    color: var(--camsprep-text);
    font-family: inherit;
    outline: none;
    min-width: 0
}

.camsprep-composer input[type="text"]::placeholder {
    color: var(--camsprep-text-muted)
}

.camsprep-attach {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: var(--camsprep-bg-soft);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    flex-shrink: 0
}

.camsprep-attach:hover {
    background: #ECEAE2
}

.camsprep-attach svg {
    width: 16px;
    height: 16px;
    fill: var(--camsprep-text-muted)
}

.camsprep-send {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: var(--camsprep-primary);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0
}

.camsprep-send:disabled {
    opacity: .4;
    cursor: not-allowed
}

.camsprep-send svg {
    width: 16px;
    height: 16px;
    fill: #fff
}

.camsprep-contact-form-v2 {
    display: flex;
    flex-direction: column;
    gap: 12px
}

.camsprep-field {
    position: relative
}

.camsprep-field input,
.camsprep-field textarea {
    width: 100%;
    border: 1px solid var(--camsprep-primary-light);
    background: #fff;
    padding: 12px 16px;
    border-radius: 12px;
    font-size: 13.5px;
    color: var(--camsprep-text);
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s, box-shadow 0.15s
}

.camsprep-field textarea {
    min-height: 90px;
    resize: vertical
}

.camsprep-field input:focus,
.camsprep-field textarea:focus {
    border-color: var(--camsprep-primary);
    box-shadow: 0 0 0 3px rgb(24 95 165 / .12)
}

.camsprep-field input::placeholder,
.camsprep-field textarea::placeholder {
    color: var(--camsprep-primary);
    opacity: .7
}

.camsprep-submit-btn {
    background: var(--camsprep-primary);
    color: #fff;
    border: none;
    padding: 14px 16px;
    border-radius: 14px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    font-family: inherit;
    margin-top: 6px;
    transition: filter 0.15s
}

.camsprep-submit-btn:hover {
    filter: brightness(1.08)
}

.camsprep-form-success {
    margin-top: 0;
    background: #E6F1FB;
    border: 1px solid var(--camsprep-primary-light);
    color: var(--camsprep-primary-dark);
    padding: 24px 20px;
    border-radius: 14px;
    font-size: 13.5px;
    text-align: center
}

.camsprep-form-success[hidden] {
    display: none
}

.camsprep-success-icon {
    width: 56px;
    height: 56px;
    margin: 0 auto 12px;
    border-radius: 50%;
    background: var(--camsprep-primary);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
    font-weight: 600
}

.camsprep-success-title {
    margin: 0 0 8px;
    font-size: 16px;
    font-weight: 600;
    color: var(--camsprep-primary-dark)
}

.camsprep-success-text {
    margin: 0 0 16px;
    color: var(--camsprep-text);
    line-height: 1.5
}

.camsprep-reset-form-btn {
    margin-top: 4px;
    max-width: 240px;
    margin-left: auto;
    margin-right: auto;
    display: block
}

.camsprep-chat-footer {
    padding: 8px 12px;
    background: #fff;
    border-top: 1px solid var(--camsprep-border);
    text-align: center;
    flex-shrink: 0
}

.camsprep-talk-human {
    background: #fff0;
    border: 1px dashed var(--camsprep-primary-light);
    color: var(--camsprep-primary);
    font-size: 12px;
    padding: 6px 12px;
    border-radius: 14px;
    cursor: pointer;
    font-family: inherit;
    transition: background 0.15s, border-color 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px
}

.camsprep-talk-human:hover {
    background: var(--camsprep-bg-soft);
    border-color: var(--camsprep-primary)
}

.camsprep-talk-human:disabled {
    cursor: default;
    opacity: .7;
    border-style: solid
}

.camsprep-talk-human-icon {
    font-size: 13px
}

.camsprep-iframe-wrap {
    flex: 1;
    overflow: hidden;
    padding: 0 4px 4px
}

.camsprep-iframe-wrap iframe {
    width: 100%;
    height: 100%;
    min-height: 460px;
    border: 0
}

.camsprep-whatsapp-pane {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    gap: 16px;
    padding: 20px
}

.camsprep-whatsapp-bubbles {
    position: relative;
    width: 180px;
    height: 140px;
    margin-bottom: 6px
}

.wa-bubble {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #E8F8EF
}

.wa-bubble svg {
    fill: var(--camsprep-success)
}

.wa-bubble-center {
    width: 70px;
    height: 70px;
    top: 35px;
    left: 55px;
    box-shadow: 0 4px 12px rgb(37 211 102 / .25)
}

.wa-bubble-center svg {
    width: 36px;
    height: 36px
}

.wa-bubble-1 {
    width: 26px;
    height: 26px;
    top: 0;
    left: 10px
}

.wa-bubble-2 {
    width: 32px;
    height: 32px;
    top: 0;
    right: 0
}

.wa-bubble-3 {
    width: 28px;
    height: 28px;
    bottom: 0;
    left: 0
}

.wa-bubble-4 {
    width: 24px;
    height: 24px;
    bottom: 8px;
    right: 18px
}

.wa-bubble-1 svg,
.wa-bubble-3 svg,
.wa-bubble-4 svg {
    width: 14px;
    height: 14px
}

.wa-bubble-2 svg {
    width: 18px;
    height: 18px
}

.camsprep-wa-btn {
    background: var(--camsprep-success);
    color: #fff;
    display: inline-block;
    width: 100%;
    max-width: 280px;
    text-decoration: none;
    text-align: center
}

.camsprep-tab-bar {
    display: flex;
    justify-content: space-around;
    align-items: center;
    background: #fff;
    border-top: 1px solid var(--camsprep-border);
    padding: 6px 4px;
    flex-shrink: 0
}

.camsprep-tab-btn {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff0;
    border: none;
    cursor: pointer;
    padding: 10px 4px;
    border-radius: 8px;
    color: var(--camsprep-text-muted);
    transition: background 0.15s, color 0.15s
}

.camsprep-tab-btn:hover {
    background: var(--camsprep-bg-soft)
}

.camsprep-tab-btn svg {
    width: 22px;
    height: 22px;
    fill: currentColor
}

.camsprep-tab-btn.camsprep-tab-active {
    color: var(--camsprep-primary);
    background: var(--camsprep-bg-soft)
}

.camsprep-powered-by {
    font-size: 10px;
    color: var(--camsprep-text-muted);
    text-align: center;
    padding: 4px;
    background: #fff;
    border-top: 1px solid #f1efe8;
    flex-shrink: 0
}

@media (max-width:480px) {
    .camsprep-panel {
        width: calc(100vw - 24px);
        max-width: 380px;
        right: 12px;
        bottom: 12px
    }
    .camsprep-bubble {
        right: 16px;
        bottom: 16px
    }
    .camsprep-greeting {
        right: 16px
    }
}

@media (prefers-reduced-motion:reduce) {
    .camsprep-panel,
    .camsprep-msg,
    .camsprep-greeting,
    .camsprep-typing span {
        animation: none !important
    }
}

